insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('des-blaue-wossa', 'des blaue Wossa', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'das blaue Wasser', '[{"kategorie": "wörtlich", "text": "[[Blauwasser-Sperma]] (Determinativkompositum aus \"Blau\"=\"Farbe\" und [[Wasser]]=\"Samenflüssigkeit\")"}, {"kategorie": "scherzhaft für", "text": "Samenflüssigkeit, Sperma (bezieht sich auf die übertriebene Menge an Sperma, die von Blauwalen bei der Ejakulation abgegeben werden soll), [[Tschuri]], [[Eiercognac]], [[kalter]] Bauer, [[Blauwossa]], [[Beidlmurra]], [[Motschka]], [[Achterl]]"}]'::jsonb, 'Mei blaus Wossa is so pickad - des kenntast ois Hoagel benutzn!'),
  ('mei-blaus-wossa-is-so-pickad-des-kenntast-ois-hoagel-benutzn', 'Mei blaus Wossa is so pickad - des kenntast ois Hoagel benutzn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mein blaues Wasser ist so pickert, das könntest du als Haargel benutzen!', '[{"kategorie": "wörtlich", "text": "\"Mein Blauwasser-Sperma ist dermaßen klebrig, das könntest du als Haargel benutzen!\"  2. Mein Sperma ist so klebrig wie das von einem Blauwal - du könntest es glatt als Haargel benutzen!  3. Mein Sperma ist so zähflüssig - du könntest dir damit die Frisur für drei Tage fixieren!"}]'::jsonb, 'des blaue Wossa'),
  ('a-wossa-mochn', 'a Wossa mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Wasser machen', '[{"kategorie": "wörtlich", "text": "\"viel Wind um etwas machen\""}, {"kategorie": "", "text": "ein Riesentheater veranstalten"}, {"kategorie": "", "text": "viel Trara um etwas machen"}, {"kategorie": "", "text": "[[einen]] Bahöl machen"}]'::jsonb, ''),
  ('in-wossa-sei', 'in Wossa sei', '', '', '', 'Wiener Kartentipplerjargon', 'im Wasser sein', '[{"kategorie": "wörtlich", "text": "\"in der Patsche sein\""}, {"kategorie": "", "text": "in Schwierigkeiten stecken"}, {"kategorie": "", "text": "in der Bredouille sein"}, {"kategorie": "", "text": "eine Pechsträhne haben"}, {"kategorie": "Kartenspielerjargon", "text": "auf der Verliererstraße sein"}]'::jsonb, 'I bin im voi im Wossa, de letztn sechs Partiin hob I olle valuan!'),
  ('i-bin-im-voi-im-wossa-de-letztn-sechs-partiin-hob-i-olle-valuan', 'I bin im voi im Wossa, de letztn sechs Partiin hob I olle valuan!', '', '', '', 'Wiener Kartentipplerjargon', 'Ich bin voll im Wasser - die letzten sechs Partien habe ich alle verloren!', '[{"kategorie": "wörtlich", "text": "\"Ich bin voll auf der Verliererstraße - die letzten sechs Partien habe ich alle verloren!\"  2. Ich hab grad ’ne echte Pechsträhne - die letzten sechs Partien habe ich allesamt verloren!  3. Ich stecke mitten in einer Niederlagenserie – sechs Spiele in Folge verloren!"}]'::jsonb, ''),
  ('ausn-wossa-sei', 'ausn Wossa sei', '', '', '', 'Grundwortschatz Wienerisch', 'aus dem Wasser sein', '[{"kategorie": "wörtlich", "text": "\"aus der Gefahrenzone sein\""}, {"kategorie": "", "text": "aus dem Gröbsten raus sein"}, {"kategorie": "", "text": "die kritische Phase hinter sich haben"}, {"kategorie": "Kartenspielerjargon", "text": "[[ausn]] Schneida sei (beim [[Schnpasen]] wenigstens einen Punkt angeschrieben haben)"}]'::jsonb, 'I woa fost petschiad, owa jetzt bin I wiida ausn Wossa!'),
  ('i-woa-fost-petschiad-owa-jetzt-bin-i-wiida-ausn-wossa', 'I woa fost petschiad, owa jetzt bin I wiida ausn Wossa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich war fast petschiert, aber jetzt bin ich wieder aus dem Wasser!', '[{"kategorie": "wörtlich", "text": "\"Ich war fast ruiniert, aber jetzt bin ich wieder aus dem Wasser!\"  2. Ich war fast ruiniert, aber jetzt bin ich wieder aus dem Gröbsten raus!  3. Ich war kurz vorm Untergehen – aber jetzt bin ich wieder im Trockenen!"}]'::jsonb, ''),
  ('frogds-mi-untan-wossa', 'Frogds mi untan Wossa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fragt mich unter dem Wasser!', '[{"kategorie": "scherzhaft für", "text": "Ich will davon nichts hören!  2. Dafür habe ich kein Ohr!  3. Ich bin im Moment für so etwas nicht ansprechbar!"}]'::jsonb, ''),
  ('dazoeoe-ma-des-untan-wossa', 'Dazöö ma des untan Wossa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Erzähl mir das unter dem Wasser!', '[{"kategorie": "scherzhaft für", "text": "Ich will davon nichts hören!  2. Dafür habe ich kein Ohr!  3. Ich bin im Moment für so etwas nicht ansprechbar!"}]'::jsonb, ''),
  ('dea-hod-so-a-waatschngsicht-dass-i-eam-in-gaunzn-toog-laung-waatschnan-kennd', 'Dea hod so a Waatschngsicht, dass I eam in gaunzn Toog laung waatschnan kennd!"', '', '', '', 'Wiener Gaunersprache', 'Der hat so ein Watschengesicht, dass ich ihn den ganzen Tag lang watschnen könnt!', '[{"kategorie": "wörtlich", "text": "\"Der hat so ein Watschengesicht, dass ich ihn den ganzen Tag lang abwatschen könnt!\"  2. Der hat ein derartiges Watschengesicht, dass du ihn rund um die Uhr ohrfeigen könntest!  3. Der hat ein Watschengesicht sondergleichen - da zuckt meine Hand ganz automatisch!"}]'::jsonb, ''),
  ('i-bin-ned-dei-waatschnmau-mid-dem-ma-ollas-mochn-kau', 'I bin ned dei Waatschnmau, mid dem ma ollas mochn kau!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich bin nicht dein Watschenmann, mit dem man alles machen kann!', '[{"kategorie": "wörtlich", "text": "\"Ich bin nicht dein Prügelknabe, mit dem du alles machen kannst!\"  2. (fig.) Ich bin nicht dein Hampelmann, mit dem man alles machen kann!  3. Ich bin nicht dein Fußabtreter, mit dem du alles machen kannst!"}]'::jsonb, ''),
  ('de-ausschbroch-wiad-a-waatschntaunz', 'De Ausschbroch wiad a Waatschntaunz!', '', '', '', 'Wiener Gaunersprache', 'Die Aussprache wird ein Watschentanz!', '[{"kategorie": "wörtlich", "text": "Diese Aussprache wird in eine direkte Konfrontation ausarten!  2. Diese Unterredung wird zum offenen Schlagabtausch!  3. Diese Debatte wird zur hitzigen Auseinandersetzung!"}]'::jsonb, ''),
  ('beim-musi-fest-haum-de-buaschn-an-waatschinga-plattld-des-woa-nix-fia-zoatbesaitete', 'Beim Musi-Fest haum de Buaschn an Waatschinga plattld – des woa nix fia Zoatbesaitete!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Beim Musikfest haben die Burschen einen Watschinger geplattelt - das war nichts für Zartbesaitete!', '[{"kategorie": "wörtlich", "text": "\"Beim Musikfest haben die Burschen einen Watschenplattler getanzt - das war nichts für Zartbesaitete!\"  2. Beim Musikfest haben die Burschen einen Watschenplattler hingelegt – das war eine echter Schlagabtausch!  3. Beim Musikfest haben die Buam einen Watschentanz geplattelt, dass die Ohren gescheppert haben!\""}]'::jsonb, ''),
  ('beim-musi-fest-haum-de-buaschn-in-waatschnplattla-taunzd-des-woa-nix-fia-zoatbesaitete', 'Beim Musi-Fest haum de Buaschn in Waatschnplattla taunzd – des woa nix fia Zoatbesaitete!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Beim Musikfest haben die Burschen den Watschenplattler getanzt - das war nichts für Zartbesaitete!', '[{"kategorie": "wörtlich", "text": "\"Beim Musikfest haben die Burschen einen Watschentanz geplattelt - das war nichts für Zartbesaitete!\"  2. Beim Musikfest haben die Burschen einen Watschenplattler hingelegt – das war eine echter Schlagabtausch!  3. Beim Musikfest haben die Buam einen Watschentanz geplattelt, dass die Ohren gescheppert haben!\""}]'::jsonb, ''),
  ('beim-musi-fest-haum-de-buaschn-an-waatschntaunz-plattld-des-woa-nix-fia-zoatbesaitete', 'Beim Musi-Fest haum de Buaschn an Waatschntaunz plattld – des woa nix fia Zoatbesaitete!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Beim Musikfest haben die Burschen einen Watschentanz geplattelt - das war nichts für Zartbesaitete!', '[{"kategorie": "wörtlich", "text": "\"Beim Musikfest haben die Burschen einen Watschenplattler getanzt - das war nichts für Zartbesaitete!\"  2. Beim Musikfest haben die Burschen einen Watschenplattler hingelegt – das war eine echter Schlagabtausch!  3. Beim Musikfest haben die Buam einen Watschentanz geplattelt, dass die Ohren gescheppert haben!\""}]'::jsonb, ''),
  ('a-waeu', 'a Wäu', '', '', '', '', 'eine Weile', '[{"kategorie": "wörtlich", "text": "\"ein Weilchen\" (vom mittelhochdeutschen \"wîle\"=\"Weile\")"}, {"kategorie": "allg.", "text": "eine Zeitlang (= unbestimmte, kürzere Zeitdauer), [[a]] Wengerl,  [[a]] Zeitl"}, {"kategorie": "fig.", "text": "über die Maßen, von vorne bis hinten, ganz schön, so was von"}]'::jsonb, 'Dea is a Wäu augsoffn!'),
  ('dea-is-a-waeu-augsoffn', 'Dea is a Wäu augsoffn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der ist hübsch angesoffen!', '[{"kategorie": "wörtlich", "text": "\"Der ist ganz schön angesoffen\""}, {"kategorie": "", "text": "Der ist ordentlich betrunken!  3. Der hat gut einen sitzen!  4. Der hat ordentlich was intus\""}]'::jsonb, 'a Wäu'),
  ('dea-is-a-waeu-deppad', 'Dea is a Wäu deppad!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der ist eine Weile deppert!', '[{"kategorie": "wörtlich", "text": "\"Der ist über die Maßen bescheuert!\"  2. Der ist so was von dumm!  3. Der ist ganz schön belämmert!"}]'::jsonb, ''),
  ('sei-ned-so-rewoeoelisch-nua-waeu-ma-di-amoi-kritisiad', 'Sei ned so rewöölisch, nua wäu ma di amoi kritisiad!', '', '', '', '', 'Sei nicht so rebellisch, nur weil man dich einmal kritisiert!', '[{"kategorie": "wörtlich", "text": "\"Sei nicht so aufmüpfig, wenn man dich mal kritisiert!\"  2. Sei nicht so bockig, nur weil man dir einmal widerspricht!  3. Sei nicht so renitent, wenn dir jemand die Meinung sagt!"}]'::jsonb, ''),
  ('mei-oide-wiad-imma-woeoelisch-waunn-i-bsoffn-bin', 'Mei Oide wiad imma wöölisch, waunn I bsoffn bin!', '', '', '', '', 'Meine Alte wird immer rebellisch, wenn ich angesoffen bin!', '[{"kategorie": "wörtlich", "text": "Meine Alte fängt immer an zu rebellieren, wenn ich angetrunken bin!  2. Meine Alte wird immer wild, wenn ich besoffen bin!  3. Meine Alte wird immer aufmüpfig, wenn ich einen sitzen habe!"}]'::jsonb, ''),
  ('mit-dem-woeoeli-brauchsd-goa-ned-easchd-diskutian', 'Mit dem Wööli brauchsd goa ned easchd diskutian!', '', '', '', '', 'Mit diesem Rebellchen brauchst du gar nicht erst zu diskutieren!', '[{"kategorie": "", "text": "Mit diesem widerspenstigen Hitzkopf brauchst du gar nicht erst zu diskutieren!  2. Mit diesem renitenten Rabauken kannst du dir jede Diskussion sparen!  3. Mit diesem bockigen Esel ist jede Diskussion zwecklos!"}]'::jsonb, ''),
  ('a-so-a-weckal', 'A so a Weckal!', '', '', '', '', 'Ein so ein Weckerl!', '[{"kategorie": "", "text": "Was für eine Witzfigur!  2. Was für ein Hampelmann!  3. Was für ein jämmerlicher Wicht!  4. Was für eine Lachnummer!"}]'::jsonb, ''),
  ('waeaech-beinaund', 'wääch beinaund', '', '', '', '', 'weh beisammen', '[{"kategorie": "", "text": "\"schlecht beisammen\""}, {"kategorie": "", "text": "in schlechter Verfassung"}, {"kategorie": "in Bezug auf Personen", "text": "kränklich, geschwächt, angeschlagen, mitgenommen, marode"}, {"kategorie": "in Bezug auf Dinge", "text": "in schlechtem Zustand, reparaturbedürftig, ramponiert, defekt"}]'::jsonb, 'I bin min Moong wääch beinaund!'),
