  ('a-waeaechs-kreiz', 'a wäächs Kreiz', '', '', '', '', 'ein wehes Kreuz', '[{"kategorie": "", "text": "ein wundes Kreuz"}, {"kategorie": "", "text": "ein schmerzender Rücken"}, {"kategorie": "", "text": "eine schmerzende Wirbelsäule"}]'::jsonb, ''),
  ('des-wegal-fiad-zua-hittn-auffe', 'Des Wegal fiad zua Hittn auffe!', '', '', '', '', 'Dieses Wegerl führt zur Hütte rauf!', '[{"kategorie": "", "text": "Dieser Fußsteig führt zur Berghütte hoch!  2. Über diesen Steig kommt man zur Gipfelhütte rauf!  3. Dieser Pfad führt dich bergauf zur Hütte!"}]'::jsonb, ''),
  ('weng-wos', 'Weng wos?', '', '', '', '', 'Wegen was?', '[{"kategorie": "wörtlich", "text": "\"Weswegen?\"  (vom mittelhochdeutschen \"wegen waz\" = \"wegen was\")"}, {"kategorie": "", "text": "Warum?  3. Aus welchem Grund?  4. Wieso?"}]'::jsonb, ''),
