  ('weng-meina', 'weng meina', '', '', '', '', 'wegen meiner', '[{"kategorie": "wörtlich", "text": "\"wegen mir\" bzw. \"meinetwegen\" (vom mittelhochdeutschen \"von minen wegen\"=\"meinetwegen\")"}, {"kategorie": "allg.", "text": "meinethalben, um meinetwillen, mir zuliebe"}, {"kategorie": "", "text": "von mir aus, wenn es nach mir geht"}]'::jsonb, 'Weng meina kaunnst ruhig fuatgee!'),
  ('weng-meina-brauchst-ned-dahaam-bleim', 'Weng meina brauchst ned dahaam bleim!', '', '', '', '', 'Wegen meiner brauchst du nicht daheim bleiben!', '[{"kategorie": "wörtlich", "text": "\"Wegen mir musst du nicht zu Hause bleiben!\"  2. Mir zuliebe musst du nicht daheim bleiben!  3. Um meinetwillen brauchst du nicht zu Hause zu bleiben!"}]'::jsonb, 'weng meina'),
