  ('in-wecka-richtn', 'in Wecka richtn', '', '', '', '', 'den Wecker richten', '[{"kategorie": "wörtlich", "text": "\"den Wecker stellen\""}, {"kategorie": "", "text": "die Weckzeit einstellen"}, {"kategorie": "", "text": "die Weckfunktion aktivieren"}]'::jsonb, ''),
