  ('do-gibds-kaane-wiaschdln', 'Do gibds kaane Wiaschdln!', '', '', '', '', 'Da gibt es keine Würschteln!', '[{"kategorie": "wörtlich", "text": "\"Hier gibt''s keine Extrawürste!\"  2. (allg.) Hier werden keine Ausnahmen gemacht!  3. Gleiche Regeln für alle!  4. Keine Ausflüchte!"}]'::jsonb, ''),
  ('vaschwindn-wias-wiaschdl-ausn-kraut', 'vaschwindn wias Wiaschdl ausn Kraut', '', '', '', '', 'verschwinden wie s'' Würschtel aus''m Kraut', '[{"kategorie": "wörtlich", "text": "\"verschwinden wie das Würstel aus dem Kraut\""}, {"kategorie": "scherzhaft für", "text": "\"\"sich schnell und unbemerkt verflüchtigen\""}, {"kategorie": "", "text": "spurlos von der Bildfläche verschwinden"}, {"kategorie": "", "text": "sich in Luft auflösen"}]'::jsonb, ''),
  ('nimm-deine-wiaschdlfinga-von-mein-toella', 'Nimm deine Wiaschdlfinga von mein Tölla!', '', '', '', '', 'Nimm deine Würschtelfinger von meinem Teller!', '[{"kategorie": "wörtlich", "text": "\"Nimm deine Wurstfinger von meinem Teller!\"  2. (allg.) Bleib mit deinen Griffeln weg von meinem Teller!  3. Finger weg von meinem Essen!  4. Nimm deine Kläweln von meinem Teller!"}]'::jsonb, ''),
  ('des-is-nua-gwuaschdld-ohne-haund-und-fuass', 'Des is nua gwuaschdld, ohne Haund und Fuaß!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das ist nur gewurschtelt, ohne Hand und Fuß!', '[{"kategorie": "wörtlich", "text": "\"Das ist nur gepfuscht, von vorne bis hinten!\"  2. (allg.) Das ist nur Stückwerk, ohne jede Struktur!  3. Das ist zusammengeschustert wie Kraut und Rüben!"}]'::jsonb, ''),
  ('soi-ma-ewig-so-weidawuaschdln', 'Soi ma ewig so weidawuaschdln?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sollen wir ewig so weiterwursteln?', '[{"kategorie": "wörtlich", "text": "\"Sollen wir ewig so planlos weitermachen?\"  2. (allg.) Sollen wir immer so vor uns hinwerkeln?  3. Wollen wir wirklich so weiterpfuschen?"}]'::jsonb, ''),
  ('bis-zua-pension-wiada-si-scho-no-iagendwii-duachwuaschdln', 'Bis zua Pension wiada si scho no iagendwii duachwuaschdln!', '', '', '', '', 'Bis zur Pension wird er sich schon noch irgendwie durchwursteln!', '[{"kategorie": "wörtlich", "text": "\"Bis zur Pension wird er sich schon noch irgendwie durchhangeln!\"  2. (scherzhaft für): \"Bis zum Ruhestand wird er sich schon noch irgendwie durchmogeln!\"  3. Irgendwie wird er sich schon noch bis zur Pensionierung durchlavieren!\""}]'::jsonb, ''),
  ('si-aussewuaschdln', 'si aussewuaschdln', '', '', '', '', 'sich herauswurschteln', '[{"kategorie": "wörtlich", "text": "\"sich herauswursteln\" (vom mittelhochdeutschen \"wursten\"=\"mit Wurstmasse hantieren\" zu \"wursteln\"=\"murksen\")"}, {"kategorie": "allg.", "text": "sich herausmogeln, sich herauswinden, sich herausmanövrieren, sich herauslavieren (aus einer misslichen Lage, etc.)"}]'::jsonb, 'Aus dem Schlamassl hoda si grod no aussegwuaschdlt!'),
  ('aus-dem-schlamassl-hoda-si-grod-no-aussegwuaschdlt', 'Aus dem Schlamassl hoda si grod no aussegwuaschdlt!', '', '', '', '', 'Aus dem Schlamassel hat er sich gerade noch herausgewurschtelt!', '[{"kategorie": "wörtlich", "text": "\"Aus diesem Schlamassel hat er sich gerade noch herausgewurstelt!\"  2. (allg.) Aus diesem Dilemma hat er sich gerade noch herausmanövriert!  3. Aus der Nummer ist er gerade noch rausgekommen!"}]'::jsonb, 'si aussewuaschdln'),
  ('wiina-wuaschdlprooda', 'Wiina Wuaschdlprooda', '', '', '', '', 'Wiener Wurstelprater', '[{"kategorie": "wörtlich", "text": "\"Wiener Vergnügungspark\"  (Determinativkompositum aus [[Wurstel]]=Verkleinerungsform von \"Hanswurst\"=[\"derb-komische Gestalt der deutschsprachigen Stegreifkomödie seit dem 16. Jahrhundert\"] und \"pratum\"=lateinisch für \"Wiesengrund\")"}, {"kategorie": "", "text": "Wiener Freizeitpark (= jener Teil des Wiener Praters, in dem sich der Spaßpark mit zahlreichen Fahrattraktionen, sowie dem [[Riesenrad]], der [[Geisterbahn]], der [[Liliputbahn]] und dem [[Schweizer]] Haus befindet).  (Der Wurstelprater verdankt seinen Namen dem \"Hanswurst\" - der von Josef Anton Stranitzky erschaffenen Hauptfigur seiner Hanswurstkomödie [\"Hanswurstiade\"])."}]'::jsonb, ''),
  ('prooda-aun', 'Prooda-Aun', '', '', '', '', 'Praterauen', '[{"kategorie": "wörtlich", "text": "\"Aulandschaft im Bereich des [[Wiener]] Praters\" (vom lateinischen \"pratum\"=\"Wiesengrund\")"}, {"kategorie": "allg.", "text": "Wiens \"grüne Lunge\""}, {"kategorie": "", "text": "Naturjuwel und Naherholungsgebiet im 2. Wiener Gemeindebezirk (duch welches der 13km lange Stadtwanderweg Nr. 9 führt). Die Auen erstrecken sich entlang der Donau und gehören zum Grünen Prater, dem weniger urbanisierten Teil des [[Praters]]."}]'::jsonb, ''),
  ('wiina-prooda', 'Wiina Prooda', '', '', '', '', 'Wiener Prater', '[{"kategorie": "allg.", "text": "\"öffentliche Parkanlage und Naherholungsgebiet ([[Grüner Prater]]) samt Vergnügungspark ([[Wurstelprater]]), die sich über eine Fläche von mehr als 6 Millionen Quadratmeter erstreckt\""}, {"kategorie": "", "text": "Ursprünglich ein Jagdgebiet für die [[Habsburger]] wurden die [[Praterauen]] erstmals 1766 für die Öffentlichkeit freigegeben. Markantestes Wahrzeichen des Wiener Wurstelpraters ist das [[Wiener]] Riesenrad."}]'::jsonb, ''),
  ('wiina-riisnrod', 'Wiina Riisnrod', '', '', '', '', 'Wiener Riesenrad', '[{"kategorie": "allg.", "text": "\"Sehenswürdigkeit und Wahrzeichen Wiens\""}, {"kategorie": "", "text": "Das Riesenrad wurde 1896 von den englischen Ingenieuren Walter Bassett Basset (1864–1907) und Harry Hitchins geplant und mit 30 Waggons (heute 15 Waggons) auf einem von Gabor Steiner (dem eigentlichen „Vater des Riesenrades“) gepachteten Grundstück 1897 zum 50. Thronjubiläum von Kaiser Franz Joseph I. als damals größtes Riesenrad der Welt auf dem Gelände des [[Wiener]] Praters errichtet. Aus 65 Metern Höhe genießt man bis heute atemberaubende Blicke auf ganz Wien."}]'::jsonb, ''),
  ('schweiza-haus', 'Schweiza Haus', '', '', '', '', 'Schweizer Haus', '[{"kategorie": "allg.", "text": "\"Wiens legendärstes Bierrestaurant mit rustikalem Biergarten im [[Wiener]] Wurstelprater\""}, {"kategorie": "", "text": "Berühmt ist das Schweizer Haus für seine dreistufige Bierzapftechnik (Vorschank, Hauptschank, Nachschank), wobei das tschechische Budweiser-Bier heute den ganzen Tag ohne Unterbrechung aus dem Zapfhahn fließt."}]'::jsonb, ''),
  ('liliput-baun', 'Liliput-Baun', '', '', '', '', 'Liliputbahn', '[{"kategorie": "allg.", "text": "\"Schmalspurbahn im Wiener Wurstelprater\""}, {"kategorie": "", "text": "Die Liliputbahn ist eine 3,9 km lange schmalspurige Parkeisenbahn im [[Wiener]] Prater auf einem Rundkurs mit mehreren Stationen, wobei sich ihr Name auf den Roman \"Gullivers Reisen\" von Jonathan Swift bezieht, in dem winzige Menschen auf einer Insel namens \"Liliput\" leben."}]'::jsonb, ''),
