  ('von-dem-wei-kriagst-launge-zend', 'Von dem Wei kriagst launge Zend!', '', '', '', '', 'Von dem Wein bekommst du lange Zähne!', '[{"kategorie": "", "text": "Bei diesem Wein zieht es dir vor lauter Säure den Mund zusammen!  2. Bei diesem Wein zieht es dir vor lauter Säure die Backen zusammen!"}]'::jsonb, ''),
