  ('schrein-wiara-zaunbrecha', 'schrein wiara Zaunbrecha', '', '', '', '', 'schreien wie ein Zahnbrecher', '[{"kategorie": "wörtlich", "text": "laut und aufdringlich schreien"}, {"kategorie": "", "text": "sich lauthals selbst rühmen, mit seiner Kunst prahlen (ohne dass etwas dahintersteckt) (\"Zahnbrecher\" = \"marktschreierischer Zähnebrecher\" [jemand, der seine ''Wunderdoktordienste'' anpreist, ohne wirklich etwas zu können])"}]'::jsonb, ''),
