  ('wem-aum-zaaga-gee', 'wem aum Zaaga gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Zeiger gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den Zeiger gehen\" (der Zeiger steht hier sinnbildlich für etwas, das sich unaufhaltsam, laut tickend und ständig vorrückend bewegt → so wie jemand, der ständig dazwischenredet oder nervt)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Wecker gehen]]"}, {"kategorie": "", "text": "[[wem aum Zwickl gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Keks gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'wem aufd Eia gee'),
  ('dei-ewiche-bessawissarei-von-geed-ma-aum-zaaga', 'Dei ewiche Bessawissarei von geed ma aum Zaaga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deine ewige Besserwisserei geht mir auf den Zeiger!', '[{"kategorie": "wörtlich", "text": "\"Deine ewige Besserwisserei geht mir voll auf den Geist!\"  2. Deine ständige Besserwisserei geht mir echt auf den Keks!  3. Mit deiner ewigen Besserwisserei gehst du mir gehörig auf die Nerven!"}]'::jsonb, ''),
  ('des-geed-ma-aum-zaaga', 'Des geed ma aum Zaaga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das geht mir auf den Zeiger!', '[{"kategorie": "wörtlich", "text": "\"Das geht mir auf den Geist!\"  2. \"Das geht mir auf die Nerven!\"  3. \"Das [[zipft]] mich an!\"  4. [[Das geht mir auf die Eier!]]  5. [[Das geht mir auf den Sack!]]  6. [[Das geht mir auf den Keks!]]  7. [[Des geed ma aum Zwicka!]]  8. [[Des geesd ma aum Wecka!]]"}]'::jsonb, ''),
  ('wem-aum-senkl-gee', 'wem aum Senkl gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Senkel gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den Senkel gehen\" (\"Senkel\"=\"Schnürsenkel\"  - Bildlich: Wenn jemand „auf den Senkel tritt“, lockert sich der Schuh, man stolpert oder wird aufgehalten. Daraus entwickelte sich: „auf den Senkel gehen“ = jemandem unangenehm werden, nerven)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Wecker gehen]]"}, {"kategorie": "", "text": "[[wem aum Zwickl gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Keks gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'Dea geed ma aum Senkl!'),
  ('waunnsd-ma-no-laung-aum-senkl-geesd-hau-i-di-beim-fensta-ausse', 'Waunnsd ma no laung aum Senkl geesd, hau I di beim Fensta ausse!', '', '', '', 'Wiener Gaunersprache', 'Wenn du mir noch lang auf den Senkel gehst, hau ich dich beim Fenster raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn du mir noch lange auf die Nerven gehst, schmeiß ich dich beim Fenster raus!\"  2. Hör auf zu nerven, sonst schmeiß ich dich raus!  3. Wenn du mir noch lange auf den Wecker gehst, fliegst du aus der Bude!"}]'::jsonb, 'wem aum Senkl gee'),
  ('wem-aum-wecka-gee', 'wem aum Wecka gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Wecker gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den Wecker gehen\" (der Wecker steht hier sinnbildlich für etwas, das sich unaufhaltsam, laut tickend und ständig vorrückend bewegt → so wie jemand, der ständig dazwischenredet oder nervt)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Zeiger gehen]]"}, {"kategorie": "", "text": "[[wem aum Zwickl gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Keks gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'Dei schdändiche Bessawissarei geed ma aum Zaaga!'),
  ('dei-schdaendiche-bessawissarei-geed-ma-aum-zaaga', 'Dei schdändiche Bessawissarei geed ma aum Zaaga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deine ständige Besserwisserei geht mir auf den Zeiger!', '[{"kategorie": "wörtlich", "text": "\"Deine ständige Besserwisserei geht mir voll auf den Geist!\"  2. Deine ständige Besserwisserei geht mir echt auf den Keks!  3. Mit deiner ewigen Besserwisserei gehst du mir gehörig auf die Nerven!"}]'::jsonb, ''),
  ('dea-geed-ma-aum-wecka', 'Dea geed ma aum Wecka!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der geht mir auf den Wecker!', '[{"kategorie": "wörtlich", "text": "\"Der geht mir auf den Geist!\"  2. \"Der geht mir auf die Nerven!\"  3. \"Der geht mir auf den [[Keks]]!\"  4. \"Der geht mir auf den Sack!\"  5. \"Der geht mir auf die Eier!\"  6. \"Dea geed ma aum Zwicka!\"  7. [[Dea geed ma aum Zaaga!]]"}]'::jsonb, ''),
  ('wem-aum-zwickl-gee', 'wem aum Zwickl gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Zwickl gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den [[Zwickel]] gehen\" (\"Zwickel\" steht hier sinnbildlich für den Stoffeinsatz im Schritt von Hosen, der bei jedem Schritt unaufhaltsam, lästig und schmerzend zwickt → so wie jemand, der ständig dazwischenredet oder nervt)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Zeiger gehen]]"}, {"kategorie": "", "text": "[[wem aum Wecka gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Keks gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'wem aufd Eia gee'),
  ('de-ewiche-keifarei-von-meina-oidn-geed-ma-uandlich-aum-zwickl', 'De ewiche Keifarei von meina Oidn geed ma uandlich aum Zwickl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die ewige Keiferei von meiner Alten geht mir ordentlich auf den Zwickel!', '[{"kategorie": "wörtlich", "text": "\"Das ewige Rumgezeter von meiner Alten geht mir voll auf den Zwickel!\"  2. Das unaufhörliche Gemecker von meiner Alten geht mir gewaltig auf den Geist!  3. Das endlose Geraunze meiner Frau geht mir mittlerweile nicht nur auf den Wecker, sondern schon voll auf den Sack!"}]'::jsonb, 'wem aum Zwickl gee'),
  ('wem-aum-zwicka-gee', 'wem aum Zwicka gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Zwicker gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den [[Zwicker]] gehen\" (\"Zwicker\" steht hier sinnbildlich für den \"Drillichanzug der Soladaten\", der bei jedem Schritt unaufhaltsam, lästig und schmerzend zwickt → so wie jemand, der ständig dazwischenredet oder nervt)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Zeiger gehen]]"}, {"kategorie": "", "text": "[[wem aum Wecka gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Keks gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'De vadaummte Woatarei geed ma uandlich aum Zwicka!'),
  ('de-vadaummte-woatarei-geed-ma-uandlich-aum-zwicka', 'De vadaummte Woatarei geed ma uandlich aum Zwicka!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die verdammte Warterei geht mir ordentlich auf den Zwicker!', '[{"kategorie": "wörtlich", "text": "\"Die verdammte Warterei geht mir voll auf den Geist!\"  2. Die ewige Warterei geht mir gewaltig auf den Wecker!  3. Das ständige Warten geht mir mächtig auf die Eier!"}]'::jsonb, 'wem aum Zwicka gee'),
  ('wem-aum-keks-gee', 'wem aum Keks gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Keks gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den [[Keks]] gehen\" (\"Keks\" steht hier sinnbildlich für \"Kopf\" → = auf den Kopf gehen → jemanden nerven)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Wecker gehen]]"}, {"kategorie": "", "text": "[[wem aum Zwickl gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Zaaga gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'wem aum Zaaga gee'),
  ('mia-geed-des-uandlich-aum-keks-dassd-imma-z-schbaeaed-kummsd', 'Mia geed des uandlich aum Keks, dassd imma z''schbääd kummsd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mir geht das ordentlich auf den Keks, dass du immer zu spät kommst!', '[{"kategorie": "wörtlich", "text": "\"Mir geht das voll auf den Geist, dass du immer zu spät kommst!\"  2. Es nervt mich total, dass du immer zu spät kommst!  3. Deine ewige Unpünktlichkeit geht mir tierisch auf den Wecker!"}]'::jsonb, 'wem aum Keks gee'),
  ('de-oide-geed-ma-gsund-aum-zwickl', 'De Oide geed ma gsund aum Zwickl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Alte geht mir gehörig auf den Zwickel!', '[{"kategorie": "wörtlich", "text": "\"Die Frau geht mir voll auf den Wecker!\"  2. \"Die geht mir mächtig auf die Nerven!\"  3. \"Die Alte zipft mich total an!\"  4. \"Das Weib geht mir voll auf die Eier!\"  5. \"Dieses Frauenzimmer geht mir total auf den Sack!\""}]'::jsonb, ''),
  ('wem-aum-schlauch-gee', 'wem aum Schlauch gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Schlauch gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den [[Schlauch]] gehen\" (\"Schlauch\" steht hier sinnbildlich für \"Fuß\" → = auf den Fuß treten → jemanden nerven)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Wecker gehen]]"}, {"kategorie": "", "text": "[[wem aum Zwickl gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Zaaga gee]]"}, {"kategorie": "", "text": "[[wem aum Keks gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'wem aum Zaaga gee'),
  ('mia-geed-des-uandlich-aum-schlauch-dass-dei-oida-imma-sein-senf-dazuageem-muass', 'Mia geed des uandlich aum Schlauch, dass dei Oida imma sein Senf dazuageem muass!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mir geht das ordentlich auf den Schlauch, dass dein Alter immer seinen Senf dazugeben muss!', '[{"kategorie": "wörtlich", "text": "\"Mir geht das voll auf den Geist, dass sich dein Mann überall einmischt!\"  2. Es nervt mich total, dass dein Alter überall und zu allem seinen Kommentar abgeben muss!  3. Dass dein Angetrauter überall ungefragt mitredet, geht mir tierisch auf den Wecker!"}]'::jsonb, ''),
  ('wem-aum-haumma-gee', 'wem aum Haumma gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Hammer gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den Hammer gehen\" (\"Hammer\" steht hier sinnbildlich für \"Hammerkopf\" → = jemandem auf den Hammerkopf gehen → jemanden durch lästiges Dazwiwschengehen an der Arbeit hindern, jemanden nerven)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Wecker gehen]]"}, {"kategorie": "", "text": "[[wem aum Zwickl gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Zaaga gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Keks gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, 'wem aum Zaaga gee'),
  ('mei-oida-geed-ma-imma-mea-aum-haumma-seit-ma-vaheirad-san', 'Mei Oida geed ma imma mea aum Haumma, seit ma vaheirad san!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mein Alter geht mir immer mehr auf den Hammer, seit wir verheiratet sind!', '[{"kategorie": "wörtlich", "text": "\"Mein Mann geht mir seit unserer Hochzeit immer mehr auf die Nerven!\"  2. Mein Partner nervt mich von Tag zu Tag mehr, seit wir zusammen leben!  3. Mein Alter geht mir seit der Hochzeit immer mehr auf den Keks!"}]'::jsonb, ''),
  ('si-zaan', 'si zaan', '', '', '', 'Grundwortschatz Wienerisch', 'sich dahinzerren', '[{"kategorie": "wörtlich", "text": "\"sich hinziehen\" (vom mittelhochdeutschen \"zarren\"=\"zerren\")"}, {"kategorie": "allg.", "text": "sich hinschleppen, kein Ende nehmen, sich in die Länge ziehen"}]'::jsonb, 'Des zaad si wiara Schdruudltaag!'),
  ('des-zaad-si', 'Des zaad si!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das zieht sich!', '[{"kategorie": "", "text": "Das zieht sich dahin!  2. Das nimmt ja kein Ende!  3. Das zieht sich endlos in die Länge!"}]'::jsonb, 'si zaan'),
  ('zaunwee-haum', 'Zaunwee haum', '', '', '', '', 'Zahnweh haben', '[{"kategorie": "", "text": "Zahnschmerzen haben"}, {"kategorie": "", "text": "von Zahnweh geplagt sein"}]'::jsonb, ''),
  ('wiina-schdefansdoom', 'Wiina Schdefansdoom', '', '', '', '', 'Wiener Stephansdom', '[{"kategorie": "wörtlich", "text": "\"der Stephansdom zu Wien\" (Wahrzeichen der Stadt Wien)"}, {"kategorie": "", "text": "[[Stephansdom]] (Mit 136 Metern Höhe ist der Stephansdom die höchste Kirche Österreichs, er befindet sich im Herzen der Wiener Innenstadt und ist 107 Meter lang, der höchste seiner vier Türme ist der Südturm mit 136 Metern)"}]'::jsonb, ''),
  ('hau-ma-eam-no-20-auffe', 'Hau ma eam no 20% auffe!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Hauen wir ihm noch 20% drauf!', '[{"kategorie": "wörtlich", "text": "\"Packen wir ihm noch 20% drauf!\"  2. Schlagen wir ihm noch 20% obendrauf!  3. Verrechnen wir ihm noch einen Aufschlag von 20%!"}]'::jsonb, ''),
