  ('wem-de-ochta-auffehaun', 'wem de Ochta auffehaun', '', '', '', 'Wiener Gaunersprache', 'jemandem die Achter raufhauen', '[{"kategorie": "wörtlich", "text": "\"jemandem die Handschellen anlegen\""}, {"kategorie": "", "text": "[[wem]] de Zangln auffehaun"}, {"kategorie": "", "text": "jemandem die Handfesseln anlegen"}]'::jsonb, 'De Kiiwara haum eam umghockd und hint aum Buugl de Ochta aufgeghaud!'),
  ('de-kiiwara-haum-eam-umghockd-und-hint-aum-buugl-de-ochta-aufgeghaud', 'De Kiiwara haum eam umghockd und hint aum Buugl de Ochta aufgeghaud!', '', '', '', 'Wiener Gaunersprache', 'Die Kieberer haben ihn umgehackt und hinten am Buckel die Achter raufgehauen!', '[{"kategorie": "wörtlich", "text": "\"Die Bullen haben ihn umgeklatscht und hinten am Rücken die Handschellen angelegt!\"  2. Die Bullen haben ihn am Boden fixiert und hinten am Rücken die Handschellen draufgedrückt!  3. Die Cops haben ihn plattgemacht und und die Eisen am Rücken festgeklickt!"}]'::jsonb, ''),
