  ('i-hob-ma-an-haufn-softwea-ausn-netz-zapft', 'I hob ma an Haufn Softwea ausn Netz zapft!', '', '', '', '', 'Ich habe mir einen Haufen Software aus dem Netz gezapft!', '[{"kategorie": "", "text": "Ich habe mir sehr viel Software aus dem Internet heruntergeladen"}]'::jsonb, ''),
  ('i-hob-an-zopfn-eigschloong', 'I hob an Zopfn eigschloong!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich habe einen Zapfen eingeschlagen!', '[{"kategorie": "wörtlich", "text": "\"Ich habe einen Zapfen ins Fass geschlagen!\"  2. Ich habe mich volllaufen lassen!  3. Ich habe einen Mordstrummrausch!"}]'::jsonb, ''),
  ('de-zopfn-haeng-ma-aum-grissbaam', 'De Zopfn häng ma aum Grissbaam!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Zapfen hängen wir an den Christbaum!', '[{"kategorie": "wörtlich", "text": "\"Die Tannenzapfen hängen wir als Deko an den Christbaum!\"  2. Mit den Tannenzapfen schmücken wir den Christbaum!  3. Die Zapfen kommen an den Weihnachtsbaum!"}]'::jsonb, ''),
  ('zopfn-eine-ins-fassl-und-scho-rinnds-bia', 'Zopfn eine ins Fassl - und scho rinnds Bia!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Zapfen rein ins Fass, und schon rinnt das Bier!', '[{"kategorie": "wörtlich", "text": "\"Zapfen rein, Hahn auf – und und schon rinnt das Bier!\"  2. Zapfen rein, Hahn auf – und das Bier fließt!  3. Anzapfen und los geht’s mit dem Bierfluss!"}]'::jsonb, ''),
  ('zopfn-rein-zopfn-raus-fertig-is-da-klaane-klaus', 'Zopfn rein, Zopfn raus - fertig is da klaane Klaus!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zapfen rein, Zapfen raus - fertig ist der kleine Klaus!', '[{"kategorie": "wörtlich", "text": "\"Stöpsel rein, Stöpsel raus - fertig ist der kleine Klaus!\"  2. Zapfhahn rein, Zapfhahn raus – fertig ist der Liebesapplaus!  3. Stecker rein, Stecker raus – und schon ist die Sache aus!  4. Knüppel rein, Knüppel raus – in Rekordzeit, lieber Klaus!"}]'::jsonb, ''),
  ('heit-hods-an-uandlichn-zopfn', 'Heit hods an uandlichn Zopfn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Heute hat es einen ordentlichen Zapfen!', '[{"kategorie": "", "text": "Heute ist es ordentlich kalt!  2. Heute herrscht klirrende Kälte! 3. Heit hods an uandlichn [[Foodn]]!"}]'::jsonb, ''),
  ('a-faescha-zopfn', 'a fäscha Zopfn', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein fescher Zapfen', '[{"kategorie": "wörtlich", "text": "\"ein fescher Kerl\""}, {"kategorie": "", "text": "ein hübscher Bursche"}, {"kategorie": "", "text": "ein stattlicher Mann"}, {"kategorie": "", "text": "ein echter Schönling"}]'::jsonb, ''),
  ('mi-hods-uandlich-zaubad', 'Mi hods uandlich zaubad!', '', '', '', '', 'Mich hat es ordentlich gezaubert!', '[{"kategorie": "", "text": "Mich hat es ordentlich gebeutelt!  2. Ich bin gehörig ins Schleudern geraten!"}]'::jsonb, ''),
  ('dea-gsoeoechde-haring-is-so-zaunraunkndia-wiara-schdrichmandal', 'Dea gsööchde Haring is so zaunraunkndia wiara Schdrichmandal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser geselchte Hering ist so zaunrankendürr wie ein Strichmanderl!', '[{"kategorie": "wörtlich", "text": "\"Dieser geräucherte Hering ist so zaunrankendürr wie ein Strichmännchen!\"  2. Dieser geräucherte Hungerhaken ist so klapperdürr wie ein Zahnstocher auf Diät!  3. Dieser ausgeräucherte Hungerhaken ist nicht einmal mehr ein Strich in der Landschaft!"}]'::jsonb, ''),
  ('de-eabsnpflaunzn-hod-raunkaln', 'De Eabsnpflaunzn hod Raunkaln!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Erbsenpflanze hat Rankerln!', '[{"kategorie": "wörtlich", "text": "\"Die Erbsenpflanze hat Kletterarme!\"  2. Die Erbsenpflanze besitzt fadenförmige Haftorgane!  3. Die Erbsenpflanze bildet Kletterranken!  4. Die Erbsenpflanze wächst mit Hilfe ihrer spiralförmigen Kletterhaken nach oben!"}]'::jsonb, ''),
  ('zaunraunkaln-san-woare-klettakinstla-sii-windn-si-an-jedn-zaun-meetahoch-auffe', 'Zaunraunkaln san woare Klettakinstla - sii windn si an jedn Zaun meetahoch auffe!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Zaunränkchen sind wahre Kletterkünstler - sie winden sich jeden Zaun meterhoch rauf!', '[{"kategorie": "wörtlich", "text": "\"Kleine Zaunranken sind wahre Kletterkünstler - sie winden sich jeden Zaun meterhoch empor!\"  2. Zarte Zaunranken sind wahre Klettermeister - Meter für Meter klimmen sie den Zaun hoch!  3. Wie grüne Akrobaten hangeln sich die kleinen Pfanzenranken an Zäunen empor, Meter für Meter!"}]'::jsonb, ''),
  ('des-raunkade-krischpindl-muass-si-aum-zaun-festhoidn-sunst-bloosd-eam-da-wind-davoo', 'Des raunkade Krischpindl muass si aum Zaun festhoidn, sunst bloosd eam da Wind davoo!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieses rankerte Krischpindl muss sich am Zaun festhalten, sonst bläst ihn der Wind davon!', '[{"kategorie": "wörtlich", "text": "\"Dieser schnurdünne Hungerhaken muss sich am Zaun festhalten, sonst bläst ihn der Wind davon!\"  2. Diese halbe Portion muss man an den Zaun binden, sonst macht er beim nächsten Windstoß einen Abflug!  3. Diese schnurdünne Gestalt muss man festbinden - sonst hebt er ab wie ein Blatt im Wind!"}]'::jsonb, ''),
  ('des-zaunraunkade-krischpindl-muass-si-aum-gatta-festhoidn-sunst-bloosd-eam-da-wind-davoo', 'Des zaunraunkade Krischpindl muass si aum Gatta festhoidn, sunst bloosd eam da Wind davoo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieses zaunrankerte Krischpindl muss sich am Gatter festhalten, sonst bläst ihn der Wind davon!', '[{"kategorie": "wörtlich", "text": "\"Dieser zaundünne Hungerhaken muss sich am Gatter festhalten, sonst bläst ihn der Wind davon!\"  2. Diese halbe Portion muss man an den Zaun binden, sonst macht er beim nächsten Windstoß einen Abflug!  3. Diese zaundünne Gestalt muss man festbinden - sonst hebt er ab wie ein Blatt im Wind!"}]'::jsonb, ''),
  ('da-efeu-schdreckd-seine-raunkadn-oam-aus-und-schleichd-si-imma-heecha', 'Da Efeu schdreckd seine raunkadn Oam aus und schleichd si imma heecha!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Der Efeu streckt seine rankigen Arme aus und schleicht sich immer höher!', '[{"kategorie": "wörtlich", "text": "\"Der Efeu streckt seine schlingenden Arme aus und klettert immer höher!\"  2. Wie stille Kletterarme schlingen sich die Triebe des Efeus immer höher empor!  3. Mit seinen schlingenden Trieben wächst der Efeu stetig in den Himmel!"}]'::jsonb, ''),
  ('da-efeu-schdreckd-seine-zaunraunkadn-oam-aus-und-schleichd-si-imma-heecha', 'Da Efeu schdreckd seine zaunraunkadn Oam aus und schleichd si imma heecha!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Efeu streckt seine zaunrankigen Arme aus und schleicht sich immer höher!', '[{"kategorie": "wörtlich", "text": "\"Der Efeu streckt seine schlingenden Arme aus und klettert den Zaun immer höher!\"  2. Wie stille Kletterarme schlingen sich die Triebe des Efeus immer höher am Zaun empor!  3. Mit seinen schlingenden Trieben wächst der Efeu am Zaun stetig in den Himmel!"}]'::jsonb, ''),
  ('do-stoeoeds-ma-de-zaeaechnnaegl-auf', 'Do stööds ma de Zäächnnägl auf!', '', '', '', '', 'Da stellt es mir die Zehennägel auf!', '[{"kategorie": "", "text": "Da stellt es mir die Haare auf!  2. Da rinnt mit der kalte Schauer über den Rücken!  3. Da schaudert es mir!"}]'::jsonb, ''),
  ('do-roids-ma-de-zaeaechnnaegl-auf', 'Do roids ma de Zäächnnägl auf!', '', '', '', '', 'Da rollt es mir die Zehennägel auf!', '[{"kategorie": "", "text": "Da stellt es mir die Haare auf!  2. Da rinnt mit der kalte Schauer über den Rücken!  3. Da schaudert es mir!"}]'::jsonb, ''),
  ('do-roids-ma-de-zaeaechnnaegl-ei', 'Do roids ma de Zäächnnägl ei!', '', '', '', '', 'Da rollt es mir die Zehennägel ein!', '[{"kategorie": "", "text": "Da stellt es mir die Haare auf!  2. Da rinnt mit der kalte Schauer über den Rücken!  3. Da schaudert es mir!"}]'::jsonb, ''),
  ('du-mochsd-a-gsichd-wiara-zrissana-zoecha', 'Du mochsd a Gsichd wiara zrissana Zöcha!', '', '', '', '', 'Du machst ein Gesicht wie ein zerrissener Zöger!', '[{"kategorie": "wörtlich", "text": "\"Du machst ein Gesicht wie ein Tragekorb, der ein Loch in seinem Strohgeflecht hat!\"  2. (fig.) Du machst ein Gesicht wie ein begossener Pudel!  3. Du machst ein Gesicht, als hättest du einen Kaktus verschluckt!  4. Du machst ein Gesicht wie sieben Tage Regenwetter!"}]'::jsonb, ''),
  ('s-zeente-moi', 's zeente Moi', '', '', '', '', 'das zehnte Mal', '[{"kategorie": "", "text": "fortwährend, immerzu"}, {"kategorie": "", "text": "alle Augenblicke wieder, immer wieder"}, {"kategorie": "", "text": "unaufhörlich, pausenlos, am laufenden Band, in einer Tour"}]'::jsonb, ''),
  ('s-zeente-moi-ned', 's zeente Moi ned', '', '', '', '', 'das zehnte Mal nicht', '[{"kategorie": "", "text": "kaum einmal, sehr selten"}, {"kategorie": "", "text": "kaum je, fast nie"}]'::jsonb, ''),
  ('des-kaunn-da-zeente-ned', 'Des kaunn da Zeente ned!', '', '', '', '', 'Das kann der Zehnte nicht!', '[{"kategorie": "", "text": "Das kann kaum jemand!  2. Das können nur die Wenigsten!"}]'::jsonb, ''),
  ('des-vadrogd-da-zeente-ned', 'Des vadrogd da Zeente ned!', '', '', '', '', 'Das verträgt der Zehnte nicht!', '[{"kategorie": "", "text": "Das hält kaum jemand aus!  2. Das vertragen nur die Wenigsten!"}]'::jsonb, ''),
  ('des-waass-da-zeente-ned', 'Des waaß da Zeente ned!', '', '', '', '', 'Das weiß der Zehnte nicht!', '[{"kategorie": "", "text": "Das weiß kaum jemand!  2. Das wissen nur die Wenigsten!"}]'::jsonb, ''),
  ('s-zeente-ned-meeng', 's Zeente ned meeng', '', '', '', '', 'das Zehnte nicht mögen', '[{"kategorie": "", "text": "vieles nicht mögen, sehr wählerisch sein"}, {"kategorie": "", "text": "sehr anspruchsvoll sein, [[haaglich]] sei"}, {"kategorie": "", "text": "nicht leicht zufriedenzustellen sein"}]'::jsonb, ''),
  ('i-hob-da-scho-s-zeente-moi-gsogt-dass-i-des-ned-wueue', 'I hob da scho s zeente Moi gsogt, dass I des ned wüü!', '', '', '', '', 'Ich hab dir schon das zehnte Mal gesagt, dass ich das nicht will!', '[{"kategorie": "", "text": "Ich habe dir immer wieder gesagt, dass ich das nicht möchte!  2. Ich habe dir in einer Tour gesagt, dass ich das nicht will!"}]'::jsonb, ''),
  ('ea-issd-des-zeente-ned', 'Ea issd des Zeente ned!', '', '', '', '', 'Er isst das Zehnte nicht!', '[{"kategorie": "", "text": "Er ist beim Essen sehr heikel!  2. Er ist beim Essen äußerst wählerisch!"}]'::jsonb, ''),
  ('do-lossd-si-da-zeente-ned-drauf-ei', 'Do lossd si da Zeente ned drauf ei!', '', '', '', '', 'Da lässt sich der Zehnte nicht drauf ein!', '[{"kategorie": "", "text": "Darauf lässt sich kaum jemand ein!  2. Darauf lassen sich nur die Wenigsten ein!"}]'::jsonb, ''),
  ('de-zeislbauan-in-da-vuaschdodt-haum-zeislwoong-baud-de-aa-auf-schottaweeg-ned-grumpaed-haum', 'De Zeislbauan in da Vuaschdodt haum Zeislwoong baud, de aa auf Schottaweeg ned grumpäd haum!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Zeiselbauer in der Vorstadt haben Zeiselwägen gefertigt, die auch auf Schotterwegen nicht gerumpelt haben!', '[{"kategorie": "wörtlich", "text": "\"Der Zeiselbauer in der Vorstadt fertigte Stellwägen, die selbst auf Schotterwegen kaum rumpelten!\"  2. In seiner Werkstatt baute der Zeiselbauer Wägen, die sanfter liefen als manch städtischer Fiaker!  3. Der Zeiselbauer aus der Vorstadt war bekannt für seine ruhigen, stabilen Ausflugswagerl – ideal auch fürs holprige Terrain!"}]'::jsonb, ''),
  ('friara-san-de-weana-min-zeislwoong-ausse-noch-grinzing-zum-heirichn-gfoan', 'Friara san de Weana min Zeislwoong ausse noch Grinzing zum Heirichn gfoan!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher sind die Wiener mit dem Zeiselwagen hinaus nach Grinzing zum Heurigen gefahren!', '[{"kategorie": "wörtlich", "text": "\"Früher sind die Wiener mit dem Stellwagen hinaus nach Grinzing zum Heurigen gefahren!\"  2. Annodazumal stiegen die Wiener in den Zeiserlwagen und ließen sich nach Grinzing kutschieren – dem Wein und dem heurigen entgegen!  3. Vor gut hundert Jahren war’s noch Brauch: Mit dem Zeiselwagen hinaus nach Grinzing – Musik, Schmäh und Heurigenstimmung inklusive!"}]'::jsonb, ''),
  ('friara-san-de-weana-min-zeisalwoong-ausse-noch-grinzing-zum-heirichn-gfoan', 'Friara san de Weana min Zeisalwoong ausse noch Grinzing zum Heirichn gfoan!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher sind die Wiener mit dem Zeiselwagen hinaus nach Grinzing zum Heurigen gefahren!', '[{"kategorie": "wörtlich", "text": "\"Früher sind die Wiener mit dem Stellwagen hinaus nach Grinzing zum Heurigen gefahren!\"  2. Annodazumal stiegen die Wiener in den Zeiserlwagen und ließen sich nach Grinzing kutschieren – dem Wein und dem heurigen entgegen!  3. Vor gut hundert Jahren war’s noch Brauch: Mit dem Zeiselwagen hinaus nach Grinzing – Musik, Schmäh und Heurigenstimmung inklusive!"}]'::jsonb, ''),
  ('aufd-wiisn-hintan-haus-samma-friara-imma-eadzeisal-schaun-gaunga', 'Aufd Wiisn hintan Haus samma friara imma Eadzeisal schaun gaunga!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Auf die Wiese hinter dem Haus sind wir früher immer ''Erdzeiserl schauen'' gegangen!', '[{"kategorie": "wörtlich", "text": "\"Auf die Wiese hinter dem Haus sind wir früher immer ''Erdhörnchen schauen'' gegangen!\"  2. Die Wiese hinter dem Haus war unser Lieblingsplatz – dort haben wir immer Erdhörnchen beobachtet!  3. Wir sind oft raus auf die Wiese, nur um die kleinen Erdhörnchen zu bestaunen!"}]'::jsonb, ''),
  ('des-zeisal-is-kaum-greessa-ois-a-blaadl-dafia-owa-umso-lauta', 'Des Zeisal is kaum greessa ois a Blaadl - dafia owa umso lauta!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Das Zeiserl ist kaum größer als ein Blatt, dafür aber umso lauter!', '[{"kategorie": "wörtlich", "text": "\"Der kleine Zeisig ist kaum größer als ein Blatt, dafür aber umso lauter!\"  2. Der Zeisig ist winzig wie ein Blatt, trillert aber lauter als ein ganzer Chor!  3. Das Zeiserl ist ein winziger Vogel mit einem erstaunlich kräftigen Stimmchen!"}]'::jsonb, ''),
  ('da-bua-is-a-richtigs-zeisal-waunn-da-wind-bloosd-muassa-si-festhoidn', 'Da Bua is a richtigs Zeisal - waunn da Wind bloosd, muassa si festhoidn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Bub ist ein richtiges Zeiserl - wenn der Wind bläst, muss er sich festhalten!', '[{"kategorie": "wörtlich", "text": "\"Der Bub ist ein richtiges Knochenbündel - wenn der Wind bläst, muss er sich festhalten!\"  2. Der Bub ist so dünn wie ein Strichmanderl - der muss sich schon beim leisesten Lüfterl am Zaun festkrallen!  3. Der Bub ist wie ein Strich in der Landschaft – ein Windstoß und er fliegt davon!"}]'::jsonb, ''),
  ('kumm-hea-mei-labs-zeisal-tua-ma-a-weng-kuschln', 'Kumm hea, mei labs Zeisal, tua ma a weng kuschln!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Komm her, mein liebes Zeisilein, tun wir ein wenig kuscheln!', '[{"kategorie": "wörtlich", "text": "\"Komm her zu mir, mein liebes Turteltäubchen, lass uns ein wenig kuscheln!\"  2. Na komm schon, mein kleines Goldkehlchen, lass uns a bisserl kuscheln!  3. Mein liebes Herzvögelein, flieg her zu mir – ich will mit dir kuscheln!"}]'::jsonb, ''),
  ('olle-heilign-zeitn-amoi', 'olle heilign Zeitn amoi', '', '', '', '', 'alle heiligen Zeiten einmal', '[{"kategorie": "", "text": "äußerst selten, kaum je"}, {"kategorie": "", "text": "sehr vereinzelt, nur gelegentlich, sporadisch"}]'::jsonb, ''),
  ('de-aepfaen-san-scho-zeitich', 'De Äpfän san scho zeitich!', '', '', '', '', 'die Äpfel sind schon zeitig', '[{"kategorie": "", "text": "Die Äpfel sind schon reif!  2. Die Äpfel sind schon reif zum Ernten!"}]'::jsonb, ''),
  ('de-weimba-zeidigd-a-waunns-in-brunn-haengd', 'De Weimba zeidigd a waunns in Brunn hängd!', '', '', '', '', 'Die Weinbeere zeitigt, auch wenn sie in Brunn hängt!', '[{"kategorie": "", "text": "Die Weinbeeren reifen auch ohne weiteren Sonnenschein!  2. Die Weintrauben werden auch ohne weiteren Sonnenschein reif zum Ernten!"}]'::jsonb, ''),
