  ('i-gee-zeidlich-schlofn-und-schdee-zeidlich-auf', 'I gee zeidlich schlofn und schdee zeidlich auf!', '', '', '', '', 'Ich geh zeitlich schlafen und steh zeitlich auf!', '[{"kategorie": "", "text": "Ich gehe früh schlafen und stehe früh auf!  2. Ich gehe zeitig zu Bett und stehe früh auf!"}]'::jsonb, ''),
  ('du-wiastas-no-zeidlich-gnua-eafoan', 'Du wiastas no zeidlich gnua eafoan!', '', '', '', '', 'Du wirst es noch zeitig genug erfahren!', '[{"kategorie": "", "text": "Du wirst es noch früh genug erfahren!  2. Du wirst es zur rechten Zeit erfahren!"}]'::jsonb, ''),
  ('ea-kriagd-a-eangrob-aum-zentraeu', 'Ea kriagd a Eangrob aum Zenträu!', '', '', '', '', 'Er kriegt ein Ehrengrab am Zentral!', '[{"kategorie": "", "text": "Er bekommt ein Ehrengrab am [[Zentralfriedhof]]"}, {"kategorie": "", "text": "Er wird in einem Ehrengrab auf dem [[Wiener]] Zentralfriedhof bestattet!"}]'::jsonb, ''),
  ('du-kaunnst-an-oidn-mau-de-zeidung-vablaadln', 'Du kaunnst an oidn Mau de Zeidung vablaadln!', '', '', '', '', 'Du kannst einem alten Mann die Zeitung verblättern!', '[{"kategorie": "", "text": "Du bist zu nichts gut!  2. Mit dir ist absolut nichts anzufangen!  3. (wörtlich): Du kannst bestenfalls einem alten Mann die Zeitung umblättern!"}]'::jsonb, ''),
