  ('an-zbreesln', 'an zbreesln', '', '', '', '', 'einen zerbröseln', '[{"kategorie": "wörtlich", "text": "\"einen zu Bröseln machen\" (vom mittelhochdeutschen \"brēsen\"=\"bröseln\")"}, {"kategorie": "scherzhaft für", "text": "einen Furz lassen, \"einen fahren lassen\", einen [[Schas]] lassen, [[an]] zdruckn, [[an]] Koffa hischdöön"}]'::jsonb, ''),
