  ('an-zdruckn', 'an zdruckn', '', '', '', '', 'einen zerdrucken', '[{"kategorie": "wörtlich", "text": "\"einen zerdrücken\" (vom mittelhochdeutschen \"drucken\"=\"drücken\")"}, {"kategorie": "scherzhaft für", "text": "einen Furz lassen, \"einen fahren lassen\", einen [[Schas]] lassen, [[an]] zdruckn, [[an]] Koffa hischdöön"}]'::jsonb, ''),
  ('si-zafetzn', 'si zafetzn', '', '', '', 'Grundwortschatz Wienerisch', 'sich zerfetzen', '[{"kategorie": "wörtlich", "text": "\"sich in Fetzen auflösen\" (vom mittelhochdeutschen \"vetze\"=\"abgerissenes Stück Stoff\")"}, {"kategorie": "fig.", "text": "sich krumm und bucklig lachen, ich kringeln vor Lachen, [[sich]] abbröseln, [[sich]] abhauen, [[sich]] abpecken, [[sich]] einen Ast lachen, [[sich]] zerbären, [[sich]] zerkugeln"}]'::jsonb, 'I zfetz mi mit dia!'),
  ('i-zfetz-mi-mit-dia', 'I zfetz mi mit dia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich zerfetze mich mit dir!', '[{"kategorie": "wörtlich", "text": "\"Ich lach mich tot mit dir!\"  2. Ich lache Tränen mit dir!  3. Mit dir zerkugle ich mich vor lauter Lachen!  4. Ich lach mich krumm und bucklig mit dir!"}]'::jsonb, ''),
  ('si-zafraunsn', 'si zafraunsn', '', '', '', 'Grundwortschatz Wienerisch', 'sich zerfransen', '[{"kategorie": "wörtlich", "text": "\"sich in feine Fäden auflösen\" (vom mittelhochdeutschen \"franze\"=\"Faden\")"}, {"kategorie": "fig.", "text": "sich aufreiben, sich aufopfern, [[sich]] zersprageln"}, {"kategorie": "", "text": "sich kringeln vor Lachen, [[sich]] einen Ast lachen, [[sich]] zerbären, [[sich]] zerfetzen"}]'::jsonb, 'I zfrauns mi fia di, und du riasd ned amoi in klaan Finga!'),
  ('i-zfrauns-mi-fia-di-und-du-riasd-ned-amoi-in-klaan-finga', 'I zfrauns mi fia di, und du riasd ned amoi in klaan Finga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich zerfranse mich für dich, und du rührst nicht einmal den kleinen Finger!', '[{"kategorie": "wörtlich", "text": "\"Ich opfere mich für dich auf,  rührst nicht einmal den kleinen Finger!\"  2. Ich reiße mir den Hintern auf, und du tust gar nichts!  3. Ich zerreiß mich für dich, und du bewegst keinen Finger!"}]'::jsonb, ''),
  ('i-zfrauns-mi-mit-dia', 'I zfrauns mi mit dia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich zerfranse mich mit dir!', '[{"kategorie": "wörtlich", "text": "\"Ich lach mich tot mit dir!\"  2. Ich lache Tränen mit dir!  3. Mit dir zerkugle ich mich vor lauter Lachen!  4. Ich lach mich krumm und bucklig mit dir!"}]'::jsonb, 'si zafraunsn'),
  ('si-zakriang', 'si zakriang', '', '', '', '', 'sich zerkriegen', '[{"kategorie": "", "text": "sich zerstreiten, sich zerkrachen, sich [[zertragen]]"}, {"kategorie": "", "text": "sich verkrachen, sich mit jemandem überwerfen, mit jemandem brechen"}]'::jsonb, ''),
  ('si-zakuugln', 'si zakuugln', '', '', '', '', 'sich zerkugeln', '[{"kategorie": "wörtlich", "text": "\"sich zusammenrollen wie eine Kugel\" (vom mittelhochdeutschen \"kugele\"=\"Kugel\")"}, {"kategorie": "fig.", "text": "sich krumm und bucklig lachen, sich kringeln vor Lachen, [[sich]] abbröseln, [[sich]] abhauen, [[sich]] abpecken, [[sich]] einen Ast lachen, [[sich]] zerbären, [[sich]] zerfransen, [[sich]] zernegern"}]'::jsonb, 'I zakuugl mi mit dia!'),
